--
-- Table structure for table `cases`
--

DROP TABLE IF EXISTS `cases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cases` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `client_id` int NOT NULL,
  `case_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `case_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cnr_number` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `case_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `court_forum` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Commercial Court',
  `team_id` int DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `status` enum('Open','Closed','Pending','On Hold') COLLATE utf8mb4_unicode_ci DEFAULT 'Open',
  `court_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `judge_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `filing_date` date DEFAULT NULL,
  `expected_close_date` date DEFAULT NULL,
  `budget` decimal(12,2) DEFAULT '0.00',
  `spent` decimal(12,2) DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `adverse_party` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `opposing_counsel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `corporate_affiliates` text COLLATE utf8mb4_unicode_ci,
  `witnesses` text COLLATE utf8mb4_unicode_ci,
  `fir_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `police_station` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `cases_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `cases_ibfk_2` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

