INSERT INTO `cases` VALUES (1,1,1,'Apex Global Logistics v. QuickFreight Multi-Modal Logistics Pvt Ltd','Comm. O.S. No. 481/2026','KABC010048122026','Commercial Suit (Commercial Courts Act 2015)','Commercial Court',NULL,'Commercial suit for recovery of ₹1,25,00,000/- with 18% p.a. interest towards cargo spoilage under Carriage by Road Act 2007; interim injunction application under Order XXXIX Rules 1 & 2 CPC.','Open','City Civil & Commercial Court, Bengaluru','Hon\'ble Sri Justice R. Devdas','2026-01-15','2026-11-30',750000.00,246000.00,'2026-10-09 07:20:21','2026-10-09 07:20:21','QuickFreight Multi-Modal Logistics Pvt Ltd','Advocate V.K. Murthy & Associates','QuickFreight Holdings India Ltd, Apex Cargo Intermodal','David Miller (Logistics Head), Rajesh Sharma (Port Operations)',NULL,NULL),(2,1,2,'Singhania Family Custody & Matrimonial Petition (Sec 125 CrPC & Guardianship)','Matrimonial Pet. No. 112/2026','MHFC020011242026','Matrimonial & Child Custody','Family Court',NULL,'Petition under Section 7 of Family Courts Act, 1984 read with Guardians and Wards Act for interim child custody and monthly maintenance adjudication.','Open','Principal Judge Family Court, Bandra, Mumbai','Hon\'ble Smt. Justice Bharati Dangre','2026-02-01','2026-09-15',450000.00,145000.00,'2026-10-09 07:20:21','2026-10-09 07:20:21','Respondent: Dr. Ananya Singhania','Advocate Soli Dastoor & Partners','Singhania Family Holdings Trust','Dr. Arvind Joshi (Child Psychologist)',NULL,NULL),(3,2,3,'Sterling Capital Advisory v. Securities and Exchange Board of India (SEBI)','SAT Appeal No. 204/2026','MHSAT01002042026','Securities Appellate Tribunal (SAT)','NCLT Tribunal',NULL,'Appellate proceedings under Section 15T of SEBI Act, 1992 challenging regulatory adjudication order concerning AIF Category II Private Placement Memorandum (PPM) disclosures.','Pending','Securities Appellate Tribunal (SAT), Mumbai','Hon\'ble Presiding Officer Justice P.S. Dinesh Kumar','2026-02-18','2026-07-30',650000.00,285000.00