INSERT INTO `retainer_agreements` VALUES (1,1,1,'Vakalatnama & Legal Services Retainer: Apex Commercial Suit (Comm. O.S. 481/2026)','v1.0',NULL,'Retainer Draw',150000.00,4500.00,'LEGAL SERVICES ENGAGEMENT & VAKALATNAMA RETAINER AGREEMENT\nPursuant to the Advocates Act, 1961 and Bar Council of India Rules (Part VI, Chapter II)\n\n1. SCOPE OF ENGAGEMENT & VAKALATNAMA: Chambers of JusticeFlow Advocates agrees to provide comprehensive legal representation to Apex Global Logistics India Pvt Ltd in Comm. O.S. No. 481/2026 before the Hon\'ble City Civil & Commercial Court, Bengaluru. Representation encompasses drafting and settling plaints, interlocutory applications under Order XXXIX CPC, discovery under Order XI CPC, leading evidence, and final oral arguments.\n\n2. ADVOCATE RETENTION & CLIENT TRUST ESCROW: Client agrees to deposit an advance retainer of ₹1,50,000/- (Rupees One Lakh Fifty Thousand Only) into the Advocate\'s Dedicated Client Trust Escrow Account as ethically required under Bar Council of India Rule 24. Professional fee deductions shall only occur upon formal submission of itemized professional bills.\n\n3. COURT EXPENSES, STAMP DUTY & WELFARE FUND: All statutory court fees under Karnataka Court Fees and Suits Valuation Act, 1958, process fees, translation costs, and Advocate Welfare Fund stamps shall be reimbursed at actuals by the Client.\n\n4. PROFESSIONAL PRIVILEGE & DISCHARGE: All communications are strictly privileged under Section 126 of the Indian Evidence Act, 1872. Client or Counsel may terminate engagement upon formal discharge of Vakalatnama with leave of the Court.','Executed engagement agreement and stamped Vakalatnama filed before Commercial Court Registry','Signed',NULL,'Rajesh Sharma (Director, Apex Logistics)','legal@apexlogistic.com',NULL,'2026-01-16 06:00:00',NULL,1,'2026-10-09 07:20:23','2026-10-09 07:20:23'),(2,3,3,'Regulatory Advisory & SAT Litigation Engagement (Sterling Capital)','v1.0',NULL,'Retainer Draw',200000.00,3500.00,'GENERAL CORPORATE LEGAL ADVISORY & REGULATORY RETAINER AGREEMENT\nChambers of JusticeFlow Advocates & Sterling Cross Capital Advisory LLP\n\n1. SCOPE OF REGULATORY ADVISORY: Ongoing legal counsel concerning SEBI AIF Regulations, SAT litigation, FEMA compliance, and RBI cross-border fund structuring for Alternative Investment Funds (Cat II).\n\n2. MONTHLY ADVISORY DRAW: Fixed monthly retainer draw of ₹1,20,000/- per calendar month, covering up to 30 advisory hours. Specialized SAT hearing appearances billed separately at ₹35,000/- per hearing brief.','Executed regulatory retainer agreement for Securities Appellate Tribunal proceedings','Signed',NULL,'Prakash Chandra (Head Compliance, Sterling Capital)','investments@sterlingcross.com',NULL,'2026-02-20 08:45:00',NULL,2,'2026-10-09 07:20:23','2026-10-09 07:20:23'),(3,4,4,'IP Trademark Enforcement & High Court Litigation Retainer (CloudByte)','v1.0',NULL,'Flat Fee',120000.00,3500.00,'INTELLECTUAL PROPERTY LITIGATION & ENFORCEMENT RETAINER\nClient: CloudByte Infotech Pvt Ltd | Matter: High Court of Karnataka Comm. Suit No. 94/2026\n\n1. SCOPE OF REPRESENTATION: Trademark enforcement, Anton Piller civil search and seizure applications, cease & desist proceedings, and commercial injunction trial representation before the High Court of Karnataka Commercial Division.','Engagement letter sent to client board for digital signature','Sent',NULL,'Siddharth Rao (CEO, CloudByte)','contact@cloudbyteinfo.io',NULL,NULL,NULL,2,'2026-10-09 07:20:23','2026-10-09 07:20:23'),(4,6,6,'EPC Turnkey Arbitration Retainer (Adani Energy v. BHPC)','v1.0',NULL,'Hourly',350000.00,5000.00,'Arbitration agreement and Section 9 representation retainer terms.','Internal draft prepared by Managing Partner','Draft',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-10-09 07:20:23','2026-10-09 07:20:23');
/*!40000 ALTER TABLE `retainer_agreements` ENABLE KEYS */;
UNLOCK TABLES;

